const CURRENT_LOCKFILE_VERSION: u32 = 1;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Lockfile {
    #[serde(skip)]
    lockfile_version: u32,
    #[serde(skip)]
    generated_header_url: Option<String>,
    #[serde(skip)]
    tools: BTreeMap<String, Vec<LockfileTool>>,
    /// Shared conda packages: platform -> basename -> CondaPackageInfo
    /// Basename includes version+build (e.g., "ncurses-6.4-h7ea286d_0")
    #[serde(skip)]
    conda_packages: BTreeMap<String, BTreeMap<String, CondaPackageInfo>>,
    /// Shared pkgx packages: platform -> package@version -> PkgxPackageInfo
    #[serde(skip)]
    pkgx_packages: BTreeMap<String, BTreeMap<String, PkgxPackageInfo>>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub(crate) struct LockfileTool {
    pub version: String,
    pub backend: Option<String>,
    #[serde(skip_serializing_if = "BTreeSet::is_empty", default)]
    pub specifiers: BTreeSet<String>,
    #[serde(skip_serializing_if = "BTreeMap::is_empty", default)]
    pub options: BTreeMap<String, String>,
    #[serde(skip_serializing_if = "BTreeMap::is_empty", default)]
    pub platforms: BTreeMap<String, PlatformInfo>,
}

impl Default for Lockfile {
    fn default() -> Self {
        Self {
            lockfile_version: CURRENT_LOCKFILE_VERSION,
            generated_header_url: None,
            tools: BTreeMap::new(),
            conda_packages: BTreeMap::new(),
            pkgx_packages: BTreeMap::new(),
        }
    }
}

type LockfileToolKey = (String, BTreeMap<String, String>);
type MergeToolEntriesResult = (Vec<LockfileTool>, HashSet<LockfileToolKey>);

/// Type of detected or verified provenance, ordered by priority (lowest to highest).
/// The ordering is significant: during verification, higher-priority mechanisms
/// are tried first. Lockfile artifact entries separately record whether the
/// provenance was verified or only detected.
/// SLSA carries an optional URL for the provenance file (.intoto.jsonl).
///
/// If adding or reordering verified attestation variants, also update
/// `VerifiedAttestation` in `crates/vfox/src/hooks/pre_install.rs`.
#[derive(Debug, Clone, strum::Display, strum::EnumIs)]
#[strum(serialize_all = "kebab-case")]
pub(crate) enum ProvenanceType {
    Minisign,

item.aggregated_output:
