                    &lockfile,
                    &tools,
                    &target_platforms,
                    !self.tool.is_empty(),
                    !self.platform.is_empty(),
                    crate::jobs::resolve(settings.jobs, self.jobs),
                    installed.unwrap_or_default(),
                )
                .await?;
                (Vec::new(), Vec::new())
            } else {
                self.process_tools(&settings, &tools, &target_platforms, &mut lockfile)
                    .await?
            };
            let resolution_succeeded = resolution_errors.is_empty();
            all_resolution_errors.extend(resolution_errors);

            let platform_regressions =
                self.platform_regression_errors(&lockfile, &stale_versions, &results);
            if !platform_regressions.is_empty() {
                all_platform_regressions.extend(platform_regressions);
                continue;
            }

            let format_changed =
                self.upgrade && lockfile.lockfile_version() == 0 && resolution_succeeded;
            if format_changed {
                self.prepare_lockfile_format(&lockfile_path, &mut lockfile);
                if !self.bind_requests(&mut lockfile, &tools, &target_platforms) {
                    bail!(
                        "cannot upgrade {} because not every request binding was resolved",
                        display_path(&lockfile_path)
                    );
                }
            } else {
                self.bind_requests(&mut lockfile, &tools, &target_platforms);
            }

            // Prune stale versions AFTER provenance checks complete
            if !generate {
                self.prune_stale_versions(&mut lockfile, &tools);
            }
            if !self.upgrade {
                self.show_stale_version_prune_message(&lockfile_path, &stale_versions, false)?;
            }

            let successful = results
                .iter()
                .filter(|result| matches!(result.status, LockTaskStatus::Updated))
                .count();
            let skipped = results.len() - successful;
            if atomic {
                staged_upgrade_writes.push(StagedUpgradeWrite {
                    path: lockfile_path.clone(),
                    original_content,
                    lockfile,
                    summary: (!generate).then_some((successful, skipped)),
                    format_changed,
                    stale_tools,
                    stale_versions,
                });
            } else {
                // Normal lock runs preserve successful updates even if another
                // target reports a non-regressing resolution error.
                lockfile.write(&lockfile_path)?;
            }

            // Print summaries for normal writes now. Upgrade summaries are
            // deferred with their writes until every target succeeds.
            if !self.json && !atomic {
                miseprintln!(
                    "{} Updated {} platform entries ({} skipped)",
                    style("✓").green(),
                    successful,
                    skipped
                );
                miseprintln!(
                    "{} Lockfile written to {}",
                    style("✓").green(),
                    style(display_path(&lockfile_path)).cyan()
                );
            }
        }

        if !has_lock_targets && !self.json {
            // --local asks for mise.local.lock specifically, and there is no global
            // equivalent, so don't redirect that run to global scope.
            if !self.global && !self.local && self.global_config_declares_tools(ts) {
                miseprintln!(
                    "{} No tools configured to lock in this project, but global config declares tools. Run {} to lock those.",
                        arr.into_iter()
                            .filter_map(|v| v.as_str().map(String::from))
                            .collect(),
                    ),
                    _ => None,
                };
                let pkgx_runtime_env = match t.remove("pkgx_runtime_env") {
                    Some(toml::Value::Table(table)) => {
                        Some(string_table_from_toml_value(toml::Value::Table(table))?)
                    }
                    _ => None,
                };
                Ok(PkgxPackageInfo {
                    url,
                    checksum,
                    pkgx_provides,
                    pkgx_runtime_env,
                })
            }
            _ => bail!("unsupported pkgx package info format"),
        }
    }
}

fn string_table_from_toml_value(value: toml::Value) -> Result<BTreeMap<String, String>> {
    match value {
        toml::Value::Table(table) => Ok(table
            .into_iter()
            .filter_map(|(key, value)| match value {
                toml::Value::String(value) => Some((key, value)),
                _ => None,
            })
            .collect()),
        _ => Ok(BTreeMap::new()),
    }
}

fn toml_table_from_string_map(values: BTreeMap<String, String>) -> toml::Table {
    values.into_iter().map(|(k, v)| (k, v.into())).collect()
}

fn existing_lockfile_doc_url(content: &str) -> Option<String> {
    content
        .lines()
        .next()?
        .strip_prefix(LOCKFILE_HEADER_PREFIX)
        .map(str::trim)
        .filter(|url| !url.is_empty())
        .map(str::to_string)
}

fn existing_lockfile_doc_url_from_path(path: &Path) -> Option<String> {
    file::read_to_string(path)
        .ok()
        .and_then(|content| existing_lockfile_doc_url(&content))
}

impl Lockfile {
    pub(crate) fn lockfile_version(&self) -> u32 {
        self.lockfile_version
    }

    pub(crate) fn upgrade(&mut self) {
        self.lockfile_version = CURRENT_LOCKFILE_VERSION;
    }

    pub(crate) fn uses_request_bindings(&self) -> bool {
        self.lockfile_version > 0
    }

    pub(crate) fn bind_request(
        &mut self,
        short: &str,
        specifier: &str,
        version: &str,
        options: &BTreeMap<String, String>,
    ) -> bool {
        if !self.uses_request_bindings() {
            return false;
        }
        let Some(tools) = self.tools.get_mut(short) else {
            return false;
        };
        let Some(target_idx) = tools
            .iter()
            .position(|tool| tool.version == version && &tool.options == options)
        else {
            return false;
        };
        for tool in tools.iter_mut().filter(|tool| &tool.options == options) {
            tool.specifiers.remove(specifier);
        }
        tools[target_idx].specifiers.insert(specifier.to_string());
        true
    }

