                                path: lockfile_path.clone(),
                                original_content,
                                lockfile,
                                summary: None,
                                format_changed,
                                stale_tools: pruned_tools.clone(),
                                stale_versions: BTreeMap::new(),
                            });
                        } else {
                            lockfile.write(&lockfile_path)?;
