            if self.dry_run {
                self.show_dry_run(&tools, &target_platforms)?;
                let lockfile = if generate {
                    lockfile::generate::read_previous(&config, &lockfile_path, self.upgrade)?
                } else {
                    Lockfile::read(&lockfile_path)?
