                    summary: (!generate).then_some((successful, skipped)),
                    format_changed,
                    stale_tools,
                    stale_versions,
                });
            } else {
                // Normal lock runs preserve successful updates even if another
                // target reports a non-regressing resolution error.
                lockfile.write(&lockfile_path)?;
            }

            // Print summaries for normal writes now. Upgrade summaries are
            // deferred with their writes until every target succeeds.
            if !self.json && !atomic {
                miseprintln!(
                    "{} Updated {} platform entries ({} skipped)",
                    style("✓").green(),
                    successful,
                    skipped
                );
                miseprintln!(
                    "{} Lockfile written to {}",
                    style("✓").green(),
                    style(display_path(&lockfile_path)).cyan()
                );
            }
        }

        if !has_lock_targets && !self.json {
            // --local asks for mise.local.lock specifically, and there is no global
            // equivalent, so don't redirect that run to global scope.
            if !self.global && !self.local && self.global_config_declares_tools(ts) {
                miseprintln!(
                    "{} No tools configured to lock in this project, but global config declares tools. Run {} to lock those.",
                        arr.into_iter()
                            .filter_map(|v| v.as_str().map(String::from))
                            .collect(),
                    ),
                    _ => None,
                };
                let pkgx_runtime_env = match t.remove("pkgx_runtime_env") {
                    Some(toml::Value::Table(table)) => {
                        Some(string_table_from_toml_value(toml::Value::Table(table))?)
                    }
                    _ => None,
                };
                Ok(PkgxPackageInfo {
                    url,
                    checksum,
                    pkgx_provides,
                    pkgx_runtime_env,
                })
            }
            _ => bail!("unsupported pkgx package info format"),
        }
    }
}

fn string_table_from_toml_value(value: toml::Value) -> Result<BTreeMap<String, String>> {
    match value {
        toml::Value::Table(table) => Ok(table
            .into_iter()
            .filter_map(|(key, value)| match value {
                toml::Value::String(value) => Some((key, value)),
                _ => None,
            })
            .collect()),
        _ => Ok(BTreeMap::new()),
    }
}

fn toml_table_from_string_map(values: BTreeMap<String, String>) -> toml::Table {
    values.into_iter().map(|(k, v)| (k, v.into())).collect()
}

fn existing_lockfile_doc_url(content: &str) -> Option<String> {
    content
        .lines()
        .next()?
        .strip_prefix(LOCKFILE_HEADER_PREFIX)
        .map(str::trim)
        .filter(|url| !url.is_empty())
        .map(str::to_string)
}

fn existing_lockfile_doc_url_from_path(path: &Path) -> Option<String> {
    file::read_to_string(path)
        .ok()
        .and_then(|content| existing_lockfile_doc_url(&content))
}

